import re, os

def get_methods(path):
    with open(path) as f:
        txt = f.read()
    out = {}
    for name in ['sum','prod','min','max','var','std','mean','nansum','round','dot','trace','cumsum','cumprod','ptp','median']:
        # find "def name(" at line start or indented within class
        m = re.search(rf'\n    def {name}\((?:.|\n)*?\n    def (?!{name})', txt)
        # simpler: find method block
        m = re.search(rf'\n    def {name}\(.*?(?=\n    def |\n    @|\nclass )', txt, re.S)
        if m:
            out[name] = m.group(0)
        else:
            out[name] = None
    return out

base = '/tmp/astropy_src'
for ver in ['5.0.5','5.1','5.2.2']:
    p = os.path.join(base, f'extract_{ver}', f'astropy-{ver}', 'astropy', 'units', 'quantity.py')
    methods = get_methods(p)
    print(f"\n\n########## ASTROPY {ver} ##########")
    for name in ['var','std','mean','nansum']:
        print(f"--- {name} ---")
        print(methods[name])
"}

